# Check all L-shapes and flag arrows
def is_L(cl):
    """Check if shape is L (corner shape)"""
    ys = {y for y, x in cl}
    xs = {x for y, x in cl}
    for (cy, cx) in cl:
        vcol = [y for y in ys if (y, cx) in set(cl)]
        hrow = [x for x in xs if (cy, x) in set(cl)]
        if len(vcol) + len(hrow) - 1 == len(cl):
            correct = {(y, cx) for y in vcol} | {(cy, x) for x in hrow}
            if set(cl) == correct:
                vcol.sort()
                hrow.sort()
                if all(vcol[i+1] - vcol[i] == 1 for i in range(len(vcol) - 1)) and \
                   all(hrow[i+1] - hrow[i] == 1 for i in range(len(hrow) - 1)) and \
                   (cy == vcol[0] or cy == vcol[-1]) and (cx == hrow[0] or cx == hrow[-1]):
                    return True
    return False

print("\n\nAll L-shapes:")
for c, cl in objs:
    if is_L(cl):
        ys = {y for y, x in cl}
        xs = {x for y, x in cl}
        print(f"  Color {c} ({len(cl)} cells): row {min(ys)}-{max(ys)}, col {min(xs)}-{max(xs)}")

# Now let's check for canon shape duplicates (twin shapes)
def canon(cl):
    """Get canonical form for shape comparison"""
    ys = {y for y, x in cl}
    xs = {x for y, x in cl}
    dy0, dx0 = min(ys), min(xs)
    return frozenset((y-dy0, x-dx0) for y, x in cl)

by_canon = defaultdict(list)
for c, cl in objs:
    can = canon(cl)
    by_canon[(c, can)].append(c)

print(f"\n\nCanon shapes (by color):")
for (c, can), cl_list in by_canon.items():
